import{_ as o,o as e,c as a,a4 as i}from"./chunks/framework.DzJZdBQK.js";const p=JSON.parse('{"title":"Solon Cloud —— 介绍","description":"","frontmatter":{"date":"2025-02-21T21:50:36","title":"Solon Cloud —— 介绍","categories":["教程100","写作","Solon","Solon 实用教程"],"tags":["教程100","写作","Solon","Solon 实用教程"]},"headers":[{"level":2,"title":"说明","slug":"说明","link":"#说明","children":[]},{"level":2,"title":"微服务","slug":"微服务","link":"#微服务","children":[]},{"level":2,"title":"云原生","slug":"云原生","link":"#云原生","children":[]},{"level":2,"title":"Solon Cloud","slug":"solon-cloud","link":"#solon-cloud","children":[]},{"level":2,"title":"书籍推荐","slug":"书籍推荐","link":"#书籍推荐","children":[{"level":3,"title":"《微服务架构设计模式》","slug":"《微服务架构设计模式》","link":"#《微服务架构设计模式》","children":[]},{"level":3,"title":"《微服务设计》","slug":"《微服务设计》","link":"#《微服务设计》","children":[]},{"level":3,"title":"The Twelve-factor App","slug":"the-twelve-factor-app","link":"#the-twelve-factor-app","children":[]}]},{"level":2,"title":"技术栈","slug":"技术栈","link":"#技术栈","children":[]}],"relativePath":"posts/course100/028.md","filePath":"posts/course100/028.md"}'),t={name:"posts/course100/028.md"};function n(r,l,d,c,s,h){return e(),a("div",null,[...l[0]||(l[0]=[i('<h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>前面的章节，我们讲解了 Solon 的开发应用，接下来准备讲解 Solon Cloud 的的开发。Solon Cloud 是为微服务和云原生准备的分布式开发套件。</p><h2 id="微服务" tabindex="-1">微服务 <a class="header-anchor" href="#微服务" aria-label="Permalink to &quot;微服务&quot;">​</a></h2><p>就像 MVC 一样，对于微服务的理解也是有不同的。微服务是一组协调工作的小而自治的服务。微服务是一组分布式的架构框架。</p><p>微服务有支持异构，弹性，易扩展，容易替换等优点，但也增加了开发、测试、部署、运维的复杂性。</p><h2 id="云原生" tabindex="-1">云原生 <a class="header-anchor" href="#云原生" aria-label="Permalink to &quot;云原生&quot;">​</a></h2><p>为了解决微服务（或者系统）的开发、部署、运维的复杂性，CNCF （Cloud Native Computing Foudation）提出了云原生的概念，就是利用各组织在共有云、私有云和混合云等新型动态环境中，构建和运行可弹性扩展的应用。主要涉及DevOps，CI/CD，Micro Service，Contianer等四个大的方面。</p><h2 id="solon-cloud" tabindex="-1">Solon Cloud <a class="header-anchor" href="#solon-cloud" aria-label="Permalink to &quot;Solon Cloud&quot;">​</a></h2><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=MjUxZDZmMjRiMmJmOGYzNzAyMTI0ZjU2M2E5OTZmZmRfcmNhUEJsRng3SnBpZ0N0TUw4TUpGRjI0TWljUU5jYThfVG9rZW46VE9zMmJtcktKbzVYQXJ4ZEJ3TWM0NHVLbjFiXzE3NDAxNDYyODI6MTc0MDE0OTg4Ml9WNA" alt="img"></p><p>从上图，我们可以看到 Solon Cloud 的主要组成部分：</p><ul><li>Solon Cloud Gateway 分布式网关相关插件</li><li>Solon Cloud Config 分布式配置相关插件</li><li>Solon Cloud Discovery 分布式注册与发现相关插件</li><li>Solon Cloud Event 分布式时间总线相关插件</li><li>Solon Cloud Job 分布式任务调度插件</li><li>Solon Cloud File 分布式文件插件</li><li>Solon Cloud Log 分布式日志插件</li><li>Solon Cloud Trace 分布式跟踪插件</li><li>Solon Cloud Metrics 分布式监控插件</li><li>Solon Cloud Breaker 分布式熔断插件</li><li>Solon Cloud Id 分布式 ID 插件</li><li>Solon Cloud I18n 分布式国际化配置插件</li><li>Solon Cloud List 分布式名单，白名单、黑名单等</li><li>Solon Cloud Lock 分布式锁插件</li></ul><p>我们可以看到Solon Cloud 其实是定义了一组接口规范，在这个接口规范的基础上实现不同分布式组件的插件。</p><p>在 Solon 的官网中也对分布式设计做了引导，我这里列出重点的部分，详细内容可查看官网 <a href="https://solon.noear.org/article/638%E3%80%82" target="_blank" rel="noreferrer">https://solon.noear.org/article/638。</a></p><ol><li>构建可水平扩展的计算能力 <ol><li>服务无状态</li><li>服务透明化</li><li>容器弹性伸缩</li></ol></li><li>构建可水平扩展的业务能力 <ol><li>基于业务领域拆分微服务</li><li>拆分业务的主线与辅线</li><li>基于实现总线交互</li></ol></li></ol><h2 id="书籍推荐" tabindex="-1">书籍推荐 <a class="header-anchor" href="#书籍推荐" aria-label="Permalink to &quot;书籍推荐&quot;">​</a></h2><h3 id="《微服务架构设计模式》" tabindex="-1">《微服务架构设计模式》 <a class="header-anchor" href="#《微服务架构设计模式》" aria-label="Permalink to &quot;《微服务架构设计模式》&quot;">​</a></h3><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=NWI2NWJkYmVmMTM5MTk4ODIxZWU4NDJjNjllMDM1OTFfRlF5WnB4UHFTUXFhN0hGMzcyeUl3T0wycThIQWUxRnBfVG9rZW46WjZYOGJldHY5bzRLOUt4N2xoSmNhVk01bkhkXzE3NDAxNDYyODI6MTc0MDE0OTg4Ml9WNA" alt="img"></p><h3 id="《微服务设计》" tabindex="-1">《微服务设计》 <a class="header-anchor" href="#《微服务设计》" aria-label="Permalink to &quot;《微服务设计》&quot;">​</a></h3><p><img src="https://otwu9ovpkn.feishu.cn/space/api/box/stream/download/asynccode/?code=ZTlmNjA0NzViNzc3N2Q3ODY3ODIzYmZkMTU4MDgwNmZfdUJvWU5YRzNqTVlPYVNLMkNRdXNMeU1mNVRKSVFmbjZfVG9rZW46Q0JlUmJaazdFbzdpNWJ4OGxsVmN0SjhrbnhWXzE3NDAxNDYyODI6MTc0MDE0OTg4Ml9WNA" alt="img"></p><h3 id="the-twelve-factor-app" tabindex="-1">The Twelve-factor App <a class="header-anchor" href="#the-twelve-factor-app" aria-label="Permalink to &quot;The Twelve-factor App&quot;">​</a></h3><p><a href="https://12factor.net/" target="_blank" rel="noreferrer">https://12factor.net/</a></p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>在本教程的介绍中说到，本教程更面向使用，因此会限制技术栈，对于Solon Cloud 的使用也是一样的，基础的服务：</p><ul><li>Nacos2 配置管理、服务发现。</li><li>Redis，分布式 ID，分布式锁等。</li><li>Skywalking，链路跟踪。</li><li>Kafka 消息服务。</li><li>Sentinel 熔断</li></ul>',24)])])}const m=o(t,[["render",n]]);export{p as __pageData,m as default};
